// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalBootstrapCoverageReviewTest {

	@TempDir
	Path directory;

	@Test
	void synchronousBootstrapCoversValidUnicodeValueAcceptedByWriterAndReader() throws Exception {
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		Path log = directory.resolve("bootstrap-coverage.log");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process process = new ProcessBuilder(java, "-Xmx64m", "-XX:+ExitOnOutOfMemoryError", "-ea", "-cp", classpath,
				ValueStoreWalBootstrapCoverageReviewTest.class.getName(), directory.toString())
						.redirectErrorStream(true)
						.redirectOutput(log.toFile())
						.start();
		boolean exited;
		try {
			exited = process.waitFor(60, TimeUnit.SECONDS);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				process.waitFor(10, TimeUnit.SECONDS);
			}
		}
		String output = Files.readString(log);
		assertThat(exited).withFailMessage("Bootstrap coverage probe timed out:%n%s", output).isTrue();
		assertThat(process.exitValue()).withFailMessage("Bootstrap coverage probe failed:%n%s", output).isZero();
	}

	public static void main(String[] args) throws Exception {
		Path directory = Path.of(args[0]);
		Literal value = SimpleValueFactory.getInstance().createLiteral("\u6f22".repeat(900_000));
		Path original = Files.createDirectory(directory.resolve("original"));
		ValueStoreWalConfig originalConfig = config(directory.resolve("original-wal"));
		int originalId;
		try (ValueStoreWAL wal = ValueStoreWAL.open(originalConfig);
				ValueStore store = new ValueStore(original.toFile(), false, 16, 16, 16, 16, wal)) {
			originalId = store.storeValue(value);
			store.awaitWalDurable(store.drainPendingWalHighWaterMark().orElseThrow());
			store.sync();
		}
		if (!value.getLabel().equals(dictionary(originalConfig).get(originalId).lexical())) {
			throw new AssertionError("Fresh writer/reader did not preserve the control value");
		}
		System.out.println("Fresh writer and reader preserve the valid Unicode literal");

		Path legacy = Files.createDirectory(directory.resolve("legacy"));
		int legacyId;
		try (ValueStore store = new ValueStore(legacy.toFile())) {
			legacyId = store.storeValue(value);
			store.sync();
		}
		ValueStoreWalConfig bootstrapConfig = config(directory.resolve("bootstrap-wal"));
		try (ValueStoreWAL wal = ValueStoreWAL.open(bootstrapConfig);
				ValueStore store = new ValueStore(legacy.toFile(), false, 16, 16, 16, 16, wal)) {
			if (!value.equals(store.getValue(legacyId))) {
				throw new AssertionError("Existing valid value cannot be read from values.dat");
			}
			store.storeValue(SimpleValueFactory.getInstance().createBNode("after-bootstrap"));
			store.awaitWalDurable(store.drainPendingWalHighWaterMark().orElseThrow());
			store.sync();
		}
		ValueStoreWalRecord bootstrapped = dictionary(bootstrapConfig).get(legacyId);
		if (bootstrapped == null || !value.getLabel().equals(bootstrapped.lexical())) {
			throw new AssertionError("Synchronous bootstrap returned and a subsequent mint became durable, "
					+ "but the existing valid ID " + legacyId + " has no complete WAL entry ("
					+ value.getLabel().length() + " characters; "
					+ value.getLabel().getBytes(StandardCharsets.UTF_8).length + " UTF-8 bytes)");
		}
	}

	private static ValueStoreWalConfig config(Path directory) {
		return ValueStoreWalConfig.builder()
				.walDirectory(directory)
				.storeUuid("bootstrap-coverage-review")
				.syncBootstrapOnOpen(true)
				.build();
	}

	private static Map<Integer, ValueStoreWalRecord> dictionary(ValueStoreWalConfig config) throws Exception {
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			ValueStoreWalRecovery.ReplayReport report = new ValueStoreWalRecovery().replayWithReport(reader);
			if (!report.complete()) {
				throw new AssertionError("WAL fixture framing is incomplete");
			}
			return report.dictionary();
		}
	}
}
